import fs from "node:fs/promises";
import path from "node:path";
import { randomUUID } from "node:crypto";
import { AppError, AppErrorCode } from "../errors.js";
import type { ArtifactStorage, StoredArtifact } from "./artifactStorage.js";

/**
 * Validates that a storage key is a safe, single path component generated by
 * the application. Rejects traversal, separators, and dot segments.
 */
function assertSafeKey(key: string): void {
  if (typeof key !== "string" || key.trim() === "") {
    throw new AppError(AppErrorCode.ValidationError, 400, "Invalid storage key");
  }
  if (key.includes("/") || key.includes("\\") || key.includes("\0")) {
    throw new AppError(AppErrorCode.ValidationError, 400, "Unsafe storage key");
  }
  if (key === "." || key === "..") {
    throw new AppError(AppErrorCode.ValidationError, 400, "Unsafe storage key");
  }
}

export class LocalArtifactStorage implements ArtifactStorage {
  private readonly baseDir: string;

  constructor(baseDir: string) {
    if (typeof baseDir !== "string" || baseDir.trim() === "") {
      throw new Error("Artifact storage directory is required");
    }
    this.baseDir = path.resolve(baseDir);
  }

  private resolvePath(key: string): string {
    assertSafeKey(key);
    const full = path.resolve(this.baseDir, key);
    const prefix = this.baseDir.endsWith(path.sep)
      ? this.baseDir
      : this.baseDir + path.sep;
    if (full !== this.baseDir && !full.startsWith(prefix)) {
      throw new AppError(AppErrorCode.ValidationError, 400, "Unsafe storage key");
    }
    return full;
  }

  async store(artifactId: string, data: Buffer): Promise<StoredArtifact> {
    if (typeof artifactId !== "string" || artifactId.trim() === "") {
      throw new AppError(AppErrorCode.ValidationError, 400, "Artifact id is required");
    }
    assertSafeKey(artifactId);
    const storageKey = artifactId;
    const target = this.resolvePath(storageKey);

    await fs.mkdir(this.baseDir, { recursive: true });

    // Temp file in the same directory so the final rename/link stays atomic.
    const tmp = path.join(this.baseDir, `.${storageKey}.${randomUUID()}.tmp`);
    try {
      await fs.writeFile(tmp, data);
      // Exclusive creation: fails if the target already exists, preventing
      // overwrite of an existing artifact even under races.
      await fs.link(tmp, target);
    } catch (e) {
      await fs.unlink(tmp).catch(() => undefined);
      const code = (e as NodeJS.ErrnoException)?.code;
      if (code === "EEXIST") {
        throw new AppError(
          AppErrorCode.Conflict,
          409,
          "Artifact already exists in storage",
        );
      }
      throw new Error(`Failed to store artifact: ${(e as Error).message}`);
    }
    await fs.unlink(tmp).catch(() => undefined);

    return { storageKey };
  }

  async retrieve(storageKey: string): Promise<Buffer> {
    const full = this.resolvePath(storageKey);
    try {
      return await fs.readFile(full);
    } catch (e) {
      throw new Error(`Failed to retrieve artifact: ${(e as Error).message}`);
    }
  }

  async delete(storageKey: string): Promise<void> {
    const full = this.resolvePath(storageKey);
    try {
      await fs.unlink(full);
    } catch (e) {
      const code = (e as NodeJS.ErrnoException)?.code;
      if (code === "ENOENT") return; // already gone
      throw new Error(`Failed to delete artifact: ${(e as Error).message}`);
    }
  }
}